import { useState } from "react";
import { Settings } from "lucide-react";
import toast from "react-hot-toast";
import { RANGOS } from "../utils/constants";

export default function Configuracion() {
  const [rangos, setRangos] = useState({
    tempMin:RANGOS.temperatura.min, tempMax:RANGOS.temperatura.max,
    phMin:RANGOS.ph.min,            phMax:RANGOS.ph.max,
    densMin:RANGOS.densidad.min,    densMax:RANGOS.densidad.max,
  });
  const set = k => e => setRangos(p=>({...p,[k]:parseFloat(e.target.value)}));
  const grupos = [
    { label:"Temperatura (°C)", items:[{label:"Mínima",key:"tempMin",step:0.5},{label:"Máxima",key:"tempMax",step:0.5}] },
    { label:"pH",               items:[{label:"Mínimo",key:"phMin",  step:0.05},{label:"Máximo",key:"phMax",  step:0.05}] },
    { label:"Densidad (g/cm³)", items:[{label:"Mínima",key:"densMin",step:0.001},{label:"Máxima",key:"densMax",step:0.001}] },
  ];
  return (
    <div style={{ padding:"28px 32px", maxWidth:580 }} className="fade-up">
      <h1 style={{ fontFamily:"'Playfair Display',serif", fontSize:36, fontWeight:800, letterSpacing:"-0.02em", marginBottom:24 }}>Configuración.</h1>
      <div className="navy-card" style={{ padding:"26px" }}>
        <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:8 }}>
          <Settings size={18} color="#6a9fd8"/>
          <p style={{ fontWeight:700, fontSize:15 }}>Umbrales de Clasificación</p>
        </div>
        <p style={{ fontSize:13, color:"rgba(255,255,255,0.45)", marginBottom:24 }}>
          Ajuste los rangos aceptables. Los cambios se aplican sin reiniciar el sistema.
        </p>
        <div style={{ display:"flex", flexDirection:"column", gap:22 }}>
          {grupos.map(({ label, items }) => (
            <div key={label}>
              <p style={{ fontSize:11, fontWeight:700, textTransform:"uppercase", letterSpacing:"0.12em", color:"#6a9fd8", marginBottom:12 }}>{label}</p>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12 }}>
                {items.map(({ label:l, key, step }) => (
                  <div key={key}>
                    <label style={{ display:"block", fontSize:11, color:"rgba(255,255,255,0.40)", marginBottom:6 }}>{l}</label>
                    <input className="input-navy" type="number" step={step} value={rangos[key]} onChange={set(key)} style={{ textAlign:"right", fontFamily:"monospace" }}/>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
        <button className="btn-navy" style={{ width:"100%", padding:"13px", fontSize:14, borderRadius:10, marginTop:24 }}
          onClick={() => toast.success("Configuración guardada y aplicada.")}>
          Guardar Configuración
        </button>
      </div>
    </div>
  );
}
